    /// <summary>0.1.9</summary>
    /// <param name="s">The document text.</param>
    /// <returns>The converted text.</returns>
    private static string Rule_0_1_9(string s)
    {
        if (PythonRegex.Search("\\\\multi", s).Success)
        {
            StdErr(PythonRegex.Format(NotSmart, "\\multi"));
        }
        return s;
    }

    /// <summary>0.1.19</summary>
    /// <param name="s">The document text.</param>
    /// <returns>The converted text.</returns>
    private static string Rule_0_1_19(string s)
    {
        if (PythonRegex.Search("\\\\octave", s).Success)
        {
            StdErr(PythonRegex.Format(NotSmart, "\\octave"));
            StdErr(UpdateManually);
        }
        return s;
    }

    /// <summary>0.1.20</summary>
    /// <param name="s">The document text.</param>
    /// <returns>The converted text.</returns>
    private static string Rule_0_1_20(string s)
    {
        s = PythonRegex.Sub("\\\\textstyle([^;]+);", "\\\\property Lyrics . textstyle = \\1", s);
        return s;
    }

