    /// <summary>1.9.4</summary>
    /// <param name="s">The document text.</param>
    /// <returns>The converted text.</returns>
    private static string Rule_1_9_4(string s)
    {
        if (PythonRegex.Search("\\figures", s).Success)
        {
            Warning("attempting automatic \\figures conversion.  Check results!");
        }
        string FiguresReplace(System.Text.RegularExpressions.Match m)
        {
            var text = m.Groups[1].Value;
            text = PythonRegex.Sub("<", "@FIGOPEN@", text);
            text = PythonRegex.Sub(">", "@FIGCLOSE@", text);
            return PythonRegex.Format("\\figures { %s }", text);
        }

        s = PythonRegex.Sub("\\\\figures[ \\t\\n]*{([^}]+)}", FiguresReplace, s);
        s = PythonRegex.Sub("\\\\<", "@STARTCRESC@", s);
        s = PythonRegex.Sub("\\\\>", "@STARTDECRESC@", s);
        s = PythonRegex.Sub("([-^_])>", "\\1@ACCENT@", s);
        s = PythonRegex.Sub("<<", "@STARTCHORD@", s);
        s = PythonRegex.Sub(">>", "@ENDCHORD@", s);
        s = PythonRegex.Sub(">", "@ENDSIMUL@", s);
        s = PythonRegex.Sub("<", "@STARTSIMUL@", s);
        s = PythonRegex.Sub("@STARTDECRESC@", "\\\\>", s);
        s = PythonRegex.Sub("@STARTCRESC@", "\\\\<", s);
        s = PythonRegex.Sub("@ACCENT@", ">", s);
        s = PythonRegex.Sub("@ENDCHORD@", ">", s);
        s = PythonRegex.Sub("@STARTCHORD@", "<", s);
        s = PythonRegex.Sub("@STARTSIMUL@", "<<", s);
        s = PythonRegex.Sub("@ENDSIMUL@", ">>", s);
        s = PythonRegex.Sub("@FIGOPEN@", "<", s);
        s = PythonRegex.Sub("@FIGCLOSE@", ">", s);
        return s;
    }

