    private static string Rule_2_1_19(string s)
    {
        if (PythonRegex.Search("include \"drumpitch", s).Success)
        {
            StdErr("Drums found. Enclose drum notes in \\drummode");
        }
        s = PythonRegex.Sub("\\\\include \"drumpitch-init.ly\"", "", s);
        s = PythonRegex.Sub("\\\\pitchnames ", "pitchnames = ", s);
        s = PythonRegex.Sub("\\\\chordmodifiers ", "chordmodifiers = ", s);
        s = PythonRegex.Sub("\\bdrums\\b\\s*=", "drumContents = ", s);
        s = PythonRegex.Sub("\\\\drums\\b", "\\\\drumContents ", s);
        if (PythonRegex.Search("drums->paper", s).Success)
        {
            StdErr(PythonRegex.Format("\n%s found. Check file manually!\n", "Drum notation"));
        }
        s = PythonRegex.Sub("\\\\apply\\s+#\\(drums->paper\\s+'([a-z]+)\\)", "\\\\property DrumStaff.drumStyleTable = #\\1-style", s);
        if (PythonRegex.Search("Thread", s).Success)
        {
            StdErr(PythonRegex.Format("\n%s found. Check file manually!\n", "Thread"));
        }
        s = PythonRegex.Sub((("(\\\\once\\s*)?\\\\property\\s+Thread\\s*\\.\\s*NoteHead\\s*" + "\\\\(set|override)\\s*#'style\\s*=\\s*#'harmonic") + "\\s+([a-z]+[,'=]*)([0-9]*\\.*)"), "<\\3\\\\harmonic>\\4", s);
        s = PythonRegex.Sub("\\\\new Thread", "\\\\context Voice", s);
        s = PythonRegex.Sub("Thread", "Voice", s);
        if (PythonRegex.Search("\u0008Lyrics\u0008", s).Success)
        {
            StdErr(PythonRegex.Format("\n%s found. Check file manually!\n", "Lyrics"));
        }
        s = PythonRegex.Sub("LyricsVoice", "L@ricsVoice", s);
        s = PythonRegex.Sub("\\bLyrics\\b", "LyricsVoice", s);
        s = PythonRegex.Sub("LyricsContext", "LyricsVoiceContext", s);
        s = PythonRegex.Sub("L@ricsVoice", "LyricsVoice", s);
        return s;
    }

