    /// <summary>2.5.13</summary>
    /// <param name="s">The document text.</param>
    /// <returns>The converted text.</returns>
    private static string Rule_2_5_13(string s)
    {
        string Func(System.Text.RegularExpressions.Match match)
        {
            var encoding = match.Groups[1].Value;
            if ((encoding == "latin1"))
            {
                return match.Groups[2].Value;
            }
            StdErr(PythonRegex.Format(NotSmart, PythonRegex.Format("\\encoding: %s", encoding)));
            StdErr("LilyPond source must be UTF-8");
            StdErr("\n");
            if ((encoding == "TeX"))
            {
                StdErr("Try the texstrings backend");
                StdErr("\n");
            }
            else
            {
                StdErr(PythonRegex.Format("Do something like: %s", PythonRegex.Format("recode %s..utf-8 FILE", encoding)));
                StdErr("\n");
            }
            StdErr("Or save as UTF-8 in your editor");
            StdErr("\n");
            throw new FatalConversionError();
        }

        s = PythonRegex.Sub("\\\\encoding\\s+\"?([a-zA-Z0-9]+)\"?(\\s+)", Func, s);
        s = PythonRegex.Sub("#\\(ly:set-point-and-click '[a-z-]+\\)", "", s);
        return s;
    }

