            StdErr("\n\\rtoe, \\ltoe, \\rheel, and \\lheel now ignore them.  Three possible solutions:\n  - use the `toeHeelStyle` context property to style the pedal mark commands\n    instead of specifying explicit directions (preferred)\n  - use normal articulations \\toe, \\vartoe, \\heel, or \\varheel\n  - remove `Toe_heel_engraver`\n");
            StdErr(UpdateManually);
        }
        return s;
    }

