    /// <summary>2.25.35</summary>
    /// <param name="s">The document text.</param>
    /// <returns>The converted text.</returns>
    private static string Rule_2_25_35(string s)
    {
        s = PythonRegex.Sub("\"?\\\\\\\\?\\%\"?\\s*=\\s*\\\\repeat\\s*percent\\s*\\\\etc\\b", "", s);
        if (PythonRegex.Search("\"?\\\\\\\\?\\%\"?\\s*=", s).Success)
        {
            StdErr(PythonRegex.Format(NotSmart, "assignment of \\%"));
            StdErr("\n\\% is now a built-in abbreviation for \\repeat percent.  If you have defined it\ndifferently, you may wish to change the name to avoid confusion.\n");
            StdErr(UpdateManually);
        }
        s = PythonRegex.Sub("\"?\\\\\\\\?\\*\"?\\s*=\\s*\\\\repeat\\s*unfold\\s*\\\\etc\\b", "", s);
        if (PythonRegex.Search("\"?\\\\\\\\?\\*\"?\\s*=", s).Success)
        {
            StdErr(PythonRegex.Format(NotSmart, "assignment of \\*"));
            StdErr("\n\\* is now a built-in abbreviation for \\repeat unfold.  If you have defined it\ndifferently, you may wish to change the name to avoid confusion.\n");
            StdErr(UpdateManually);
        }
        s = PythonRegex.Sub("\\balteration->text-accidental-markup\\b", "accidental->text-markup", s);
        s = PythonRegex.Sub("\\bchord-name->german-markup\\b", "chord-name:german-markup", s);
        s = PythonRegex.Sub("\\bchord-name->italian-markup\\b", "chord-name:italian-markup", s);
        s = PythonRegex.Sub("\\bnote-name->german-markup\\b", "chord-name:german-lowercase-name-markup", s);
        s = PythonRegex.Sub("\\bnote-name->markup\\b", "(chord-name:markup #f)", s);
        s = PythonRegex.Sub("\\bnote-name->string\\b", "pitch->name", s);
        if (PythonRegex.Search("(?sx)\n\\\\language \\b\n.*\n\\\\ ( german | semiGerman | italian | french ) Chords \\b\n    ", s).Success)
        {
            StdErr(PythonRegex.Format(NotSmart, "chord names in combination with \\language"));
            StdErr("\n\\germanChords and its siblings no longer depend on the input note names\nas selected with \\language.  This might cause different note names in the\nshown chord names.\n");
        }
        s = PythonRegex.Sub("\\\\semiGermanChords\\b", "\\\\norwegianChords", s);
        return s;
    }

